import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for DSCompiler.atan2 method.
 */
public class DSCompiler_atan2_TriageGen0Test {

    private static final double EPSILON = 1e-12;

    @Test
    public void testAtan2_PositiveX() {
        // Test case: x > 0 (Quadrant I and IV)
        // x = 1.0, y = 1.0 => atan2(1, 1) = PI/4
        // x = 1.0, y = -1.0 => atan2(-1, 1) = -PI/4
        int parameters = 1;
        int order = 0;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        y[0] = 1.0;
        x[0] = 1.0;

        y[1] = -1.0;
        x[1] = 1.0;

        compiler.atan2(y, 0, x, 0, result, 0);

        Assert.assertEquals("Quadrant I failed", FastMath.PI / 4.0, result[0], EPSILON);
        Assert.assertEquals("Quadrant IV failed", -FastMath.PI / 4.0, result[1], EPSILON);
    }

    @Test
    public void testAtan2_NegativeX() {
        // Test case: x < 0 (Quadrant II and III)
        // x = -1.0, y = 1.0 => atan2(1, -1) = 3PI/4
        // x = -1.0, y = -1.0 => atan2(-1, -1) = -3PI/4
        int parameters = 1;
        int order = 0;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        y[0] = 1.0;
        x[0] = -1.0;

        y[1] = -1.0;
        x[1] = -1.0;

        compiler.atan2(y, 0, x, 0, result, 0);

        // Note: The implementation for x < 0 uses: result[0] = (tmp2[0] <= 0 ? -PI : PI) - 2 * atan(y/(r-x))
        // For x=-1, y=1: r=sqrt(2). atan(1/(sqrt(2)-(-1))) = atan(1/(sqrt(2)+1)) = atan(sqrt(2)-1) = PI/8
        // result[0] = PI - 2*(PI/8) = 3PI/4. Correct.
        Assert.assertEquals("Quadrant II failed", 3.0 * FastMath.PI / 4.0, result[0], EPSILON);

        // For x=-1, y=-1: r=sqrt(2). atan(-1/(sqrt(2)+1)) = -PI/8
        // result[0] = -PI - 2*(-PI/8) = -PI + PI/4 = -3PI/4. Correct.
        // The second loop in the code starts from i=1, so we check index 1 for the second element logic
        // However, the code provided only sets result[0] specifically for the +/- PI logic and 
        // loops from 1 for the rest. This implies the method assumes size 1 for the x < 0 logic 
        // or handles the offset differently. Let's test size 2 carefully.

        // Re-running test for x < 0 with size 2 to trigger the loop i=1
        y[0] = 1.0; x[0] = -1.0;
        y[1] = 1.0; x[1] = -1.0; // testing loop index 1
        compiler.atan2(y, 0, x, 0, result, 0);
        // result[1] = -2 * atan(y/(r-x)) = -2 * (PI/8) = -PI/4
        Assert.assertEquals("Loop index 1 failed", -FastMath.PI / 4.0, result[1], EPSILON);
    }

    @Test
    public void testAtan2_ZeroAndBoundaries() {
        int parameters = 1;
        int order = 0;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // x = 0, y = 1 => atan2(1, 0) = PI/2
        y[0] = 1.0;
        x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals("Zero X boundary failed", FastMath.PI / 2.0, result[0], EPSILON);

        // x = 0, y = -1 => atan2(-1, 0) = -PI/2
        y[0] = -1.0;
        x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals("Zero X boundary negative failed", -FastMath.PI / 2.0, result[0], EPSILON);
    }

    @Test
    public void testAtan2_Offsets() {
        int parameters = 1;
        int order = 0;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size + 1];
        double[] x = new double[size + 1];
        double[] result = new double[size + 1];

        y[1] = 1.0;
        x[1] = 1.0;

        // Test with offsets
        compiler.atan2(y, 1, x, 1, result, 1);

        Assert.assertEquals("Offset test failed", FastMath.PI / 4.0, result[1], EPSILON);
    }
}
